class TimeMap { private final Map<String,TreeMap<Integer,String>> timelines=new HashMap<>();public TimeMap(){}public void set(String key,String value,int timestamp){timelines.computeIfAbsent(key,k->new TreeMap<>()).put(timestamp,value);}public String get(String key,int timestamp){TreeMap<Integer,String> timeline=timelines.get(key);if(timeline==null)return "";Map.Entry<Integer,String> entry=timeline.floorEntry(timestamp);return entry==null?"":entry.getValue();} }
